const e = $input.first().json;
const wf   = e.workflow?.name || 'unknown';
const node = e.execution?.lastNodeExecuted || e.trigger?.error?.node?.name || '?';
const msg  = e.execution?.error?.message || e.trigger?.error?.message || 'unknown error';
const url  = e.execution?.url || '';
return [{ json: { text:
  `🚨 LỖI WORKFLOW\n📋 ${wf}\n📍 Node: ${node}\n❌ ${String(msg).slice(0, 500)}\n🔗 ${url}` } }];
